{
  "items": [
    {
      "name": "RingSeminorm.mul_le'",
      "module_name": "Mathlib.Analysis.Normed.Unbundled.RingSeminorm",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : NonUnitalNonAssocRing R] (self : RingSeminorm R) (x y : R),\n  self.toFun (x * y) ≤ self.toFun x * self.toFun y"
    },
    {
      "name": "seminormFromBounded_mul",
      "module_name": "Mathlib.Analysis.Normed.Unbundled.SeminormFromBounded",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {f : R → ℝ} {c : ℝ},\n  0 ≤ f →\n    (∀ (x y : R), f (x * y) ≤ c * f x * f y) →\n      ∀ (x y : R), seminormFromBounded' f (x * y) ≤ seminormFromBounded' f x * seminormFromBounded' f y"
    },
    {
      "name": "seminormFromBounded",
      "module_name": "Mathlib.Analysis.Normed.Unbundled.SeminormFromBounded",
      "kind": "definition",
      "type": "{R : Type u_1} →\n  [inst : CommRing R] →\n    {f : R → ℝ} →\n      {c : ℝ} →\n        f 0 = 0 →\n          0 ≤ f →\n            (∀ (x y : R), f (x * y) ≤ c * f x * f y) →\n              (∀ (a b : R), f (a + b) ≤ f a + f b) → (∀ (x : R), f (-x) = f x) → RingSeminorm R"
    },
    {
      "name": "seminormFromBounded_ge",
      "module_name": "Mathlib.Analysis.Normed.Unbundled.SeminormFromBounded",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {f : R → ℝ} {c : ℝ},\n  0 ≤ f → (∀ (x y : R), f (x * y) ≤ c * f x * f y) → ∀ (x : R), f x ≤ f 1 * seminormFromBounded' f x"
    },
    {
      "name": "SeminormedRing.norm_mul_le",
      "module_name": "Mathlib.Analysis.Normed.Ring.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_5} [self : SeminormedRing α] (a b : α), ‖a * b‖ ≤ ‖a‖ * ‖b‖"
    },
    {
      "name": "MulRingSeminorm.map_mul'",
      "module_name": "Mathlib.Analysis.Normed.Unbundled.RingSeminorm",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : NonAssocRing R] (self : MulRingSeminorm R) (x y : R),\n  self.toFun (x * y) = self.toFun x * self.toFun y"
    },
    {
      "name": "SeminormedRing.noConfusion",
      "module_name": "Mathlib.Analysis.Normed.Ring.Basic",
      "kind": "definition",
      "type": "{P : Sort u} →\n  {α : Type u_5} →\n    {t : SeminormedRing α} →\n      {α' : Type u_5} → {t' : SeminormedRing α'} → α = α' → t ≍ t' → SeminormedRing.noConfusionType P t t'"
    },
    {
      "name": "seminormFromBounded_of_mul_is_mul",
      "module_name": "Mathlib.Analysis.Normed.Unbundled.SeminormFromBounded",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {f : R → ℝ} {c : ℝ},\n  0 ≤ f →\n    (∀ (x y : R), f (x * y) ≤ c * f x * f y) →\n      ∀ {x : R},\n        (∀ (y : R), f (x * y) = f x * f y) →\n          ∀ (y : R), seminormFromBounded' f (x * y) = seminormFromBounded' f x * seminormFromBounded' f y"
    }
  ]
}
